// Generated by `codictator init` (SPEC §4.19.3); do not edit by hand.
// static replies below per configured harness (SPEC §4.5.1) and until then
// they are the two P0 harness deny forms by hand. Zero dependencies and
// ES2015-only syntax, so any Node parses it: the version check runs before
// any newer syntax could load, and only node: built-ins are imported. It
// sets CODICTATOR_HOOK=1 in the engine process, then resolves the engine at
// <root>/node_modules/codictator/dist/cli/main.js else
// <root>/.codictator/tool/node_modules/codictator/dist/cli/main.js. The
// launcher reads the resolved engine's manifest version and passes it
// as main's third argument, so hook validation sees the installed
// version (SPEC §4.2.1 EC-11); an unreadable manifest falls back to
// the two-argument call. A
// missing engine answers the harness's embedded static CDX-E003 block
// reply; outside hook it prints CDX-E003 and exits 6. Git hooks arrive
// as a `git` first word and the extension server as a `serve` first
// word; both route to the engine like hook words do, so a missing
// engine or an old node fails the commit, push or live view closed.
// Version arbitration
// between the root and tool-dir engines (SPEC §4.19 EC-6) belongs to the
// phase 9 CLI: until then the first candidate that exists wins.
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const MIN_NODE_MAJOR = 24;

function nodeMajor() {
	const match = /^v(\d+)\./.exec(process.version);
	if (match === null) {
		return 0;
	}
	const major = parseInt(match[1], 10);
	if (Number.isNaN(major)) {
		return 0;
	}
	return major;
}

// The launcher ships at <root>/.codictator/bin/run.mjs, so the repo root
// is three levels up from this file.
function launcherRoot() {
	return path.dirname(
		path.dirname(path.dirname(fileURLToPath(import.meta.url))),
	);
}

function engineCandidates(root) {
	return [
		path.join(root, "node_modules", "codictator", "dist", "cli", "main.js"),
		path.join(
			root,
			".codictator",
			"tool",
			"node_modules",
			"codictator",
			"dist",
			"cli",
			"main.js",
		),
	];
}

// The embedded pre-engine deny forms (SPEC §4.5.1): exit 0 with the
// harness's own deny JSON. Answers null for harnesses without a static
// form, so the caller falls back to the process exit code.
function staticReply(harness, code, message) {
	if (harness === "muse-code") {
		return {
			exitCode: 0,
			stdout: JSON.stringify({
				hookSpecificOutput: {
					hookEventName: "PreToolUse",
					permissionDecision: "deny",
					permissionDecisionReason: `${code} ${message}`,
				},
			}),
		};
	}
	if (harness === "opencode") {
		return {
			exitCode: 0,
			stdout: JSON.stringify({
				decision: "block",
				message: `${code} ${message}`,
				eventId: "static",
			}),
		};
	}
	return null;
}

function writeStatic(reply) {
	process.stdout.write(reply.stdout);
	process.exitCode = reply.exitCode;
}

function writeMissingEngine() {
	process.stderr.write(
		"CDX-E003 codictator engine is not installed; run npm ci, then retry.\n",
	);
	process.exitCode = 6;
}

function writeOldNode() {
	process.stderr.write(
		`CDX-E002 node ${process.version} is older than the required >=24.0.0; install a newer Node, then retry.\n`,
	);
	process.exitCode = 6;
}

function writeEngineFailed() {
	process.stderr.write(
		"CDX-E901 the codictator engine failed to load; the tool call is blocked.\n",
	);
	process.exitCode = 1;
}

function oldNodeMessage() {
	return (
		`node ${process.version} is older than the required >=24.0.0; ` +
		"install a newer Node, then retry the tool call."
	);
}

function firstExisting(candidates) {
	for (let index = 0; index < candidates.length; index += 1) {
		if (existsSync(candidates[index])) {
			return candidates[index];
		}
	}
	return null;
}

// SPEC §4.2.1 EC-11: the engine entry validates config.codictator
// against the installed engine version, so the launcher extracts it
// from the resolved engine's own manifest text and passes it as
// main's third argument. A version-field scan keeps JSON parsing in
// the kernel per §10.3 item 6 (and a regex literal would confuse the
// blankCode lexer the ts/lint gate runs on); any unreadable or
// version-less manifest answers null and the caller falls back to
// the two-argument call, which keeps the pinned placeholder —
// fail-closed downstream, never an allow.
function installedEngineVersion(enginePath) {
	try {
		const manifestPath = path.join(
			path.dirname(path.dirname(path.dirname(enginePath))),
			"package.json",
		);
		const text = readFileSync(manifestPath, "utf8");
		const marker = "\"version\":";
		const at = text.indexOf(marker);
		if (at === -1) {
			return null;
		}
		let index = at + marker.length;
		while (text[index] === " " || text[index] === "\t" || text[index] === "\n" || text[index] === "\r") {
			index += 1;
		}
		if (text[index] !== "\"") {
			return null;
		}
		const end = text.indexOf("\"", index + 1);
		if (end === -1) {
			return null;
		}
		const version = text.slice(index + 1, end);
		if (version === "") {
			return null;
		}
		return version;
	} catch (ignored) {
		return null;
	}
}

function reportMissing(harness) {
	const missing = staticReply(
		harness,
			"CDX-E003",
			"codictator engine is not installed; run npm ci, then retry the tool call.",
	);
	if (missing === null) {
		writeMissingEngine();
		return;
	}
	writeStatic(missing);
}

function checkNode(harness) {
	if (nodeMajor() < MIN_NODE_MAJOR) {
		const oldNode = staticReply(harness, "CDX-E002", oldNodeMessage());
		if (oldNode === null) {
			writeOldNode();
			return false;
		}
		writeStatic(oldNode);
		return false;
	}
	return true;
}

function runEngine(enginePath, args, harness) {
	process.env.CODICTATOR_HOOK = "1";
	import(pathToFileURL(enginePath).href)
		.then(
			(engine) => {
				if (engine === null || typeof engine.main !== "function") {
					throw new Error("engine entry has no main");
				}
				const version = installedEngineVersion(enginePath);
				if (version === null) {
					return engine.main(args, process.cwd());
				}
				return engine.main(args, process.cwd(), version);
			},
			(error) => {
				throw error;
			},
		)
		.then(
			(code) => {
				process.exitCode = typeof code === "number" ? code : 0;
			},
			() => {
				const failed = staticReply(
					harness,
					"CDX-E901",
					"the codictator engine failed to load; the tool call is blocked.",
				);
				if (failed === null) {
					writeEngineFailed();
					return;
				}
				writeStatic(failed);
			},
		);
}

function main() {
	const args = process.argv.slice(2);
	if (args[0] !== "hook" && args[0] !== "git" && args[0] !== "serve") {
		writeMissingEngine();
		return;
	}
	const harness = args[1] || "";
	if (!checkNode(harness)) {
		return;
	}
	const enginePath = firstExisting(engineCandidates(launcherRoot()));
	if (enginePath === null) {
		reportMissing(harness);
		return;
	}
	runEngine(enginePath, args, harness);
}
main();
